    return sum(char_width(ch) for ch in s)


def truncate_to_width(s, maxw):
    if maxw <= 0:
        return ''
    out = []
    w = 0
    for ch in s:
        cw = char_width(ch)
        if w + cw > maxw:
            break
        out.append(ch); w += cw
    return ''.join(out)


def align_text(s, width, align):
    w = disp_width(s)
    if w > width:
        s = truncate_to_width(s, width)
        w = disp_width(s)
    gap = max(0, width - w)
    if align == 'right':
        left, right = gap, 0
    elif align == 'center':
        left, right = gap // 2, gap - gap // 2
    else:
        left, right = 0, gap
    return ' ' * left + s + ' ' * right


def cell(s, content_width, padding, align):
