    if has_header:
        ncols = len(header)
    else:
        ncols = len(body[0]) if body else 0
    # Since validation guarantees fixed-length records, the first row/header establishes columns.
    widths = [0] * ncols
    def absorb(row):
        for idx, val in enumerate(row[:ncols]):
            widths[idx] = max(widths[idx], disp_width(val))
    if has_header:
        absorb(header)
        rows_to_sample = body if sample_n is None else body[:sample_n]
        for r in rows_to_sample: absorb(r)
    else:
        rows_to_sample = body if sample_n is None else body[:sample_n]
        for r in rows_to_sample: absorb(r)
    if number:
        numw = 0
        if has_header:
            numw = max(numw, 1)  # '#'
            count_rows = len(body) if sample_n is None else min(sample_n, len(body))
            for k in range(1, count_rows + 1):
                numw = max(numw, len(str(k)))
        else:
            count_rows = len(body) if sample_n is None else min(sample_n, len(body))
            for k in range(1, count_rows + 1):
                numw = max(numw, len(str(k)))
        widths = [numw] + widths
    return widths


def line_bordered(widths, style, kind, indent):
    # kind: top, sep, bottom
    if style == 'ascii':
        left = mid = right = '+'; h = '-'
    elif style == 'rounded':
        h = '─'
        if kind == 'top': left, mid, right = '╭','┬','╮'
        elif kind == 'bottom': left, mid, right = '╰','┴','╯'
        else: left, mid, right = '├','┼','┤'
    elif style == 'reinforced':
        h = '─'
        if kind == 'top': left, mid, right = '┏','┬','┓'
        elif kind == 'bottom': left, mid, right = '┗','┴','┛'
        else: left, mid, right = '├','┼','┤'
    else:  # sharp/grid
        h = '─'
        if kind == 'top': left, mid, right = '┌','┬','┐'
        elif kind == 'bottom': left, mid, right = '└','┴','┘'
        else: left, mid, right = '├','┼','┤'
    parts = [h * w for w in widths]
    return ' ' * indent + left + mid.join(parts) + right


def line_ascii2_sep(widths, indent):
    return ' ' * indent + ' ' + '+'.join('-' * w for w in widths) + ' '


def line_markdown_sep(widths, indent):
    return ' ' * indent + '|' + '|'.join('-' * w for w in widths) + '|'


def render_row(vals, widths, cfg, aligns, has_number_col=False):
    p = cfg.padding
    cwidths = [max(0, w - 2*p) for w in widths]
    pieces = []
    for i, w in enumerate(widths):
        val = vals[i] if i < len(vals) else ''
        align = aligns[i] if isinstance(aligns, list) else aligns
        pieces.append(cell(val, cwidths[i], p, align))
    ind = ' ' * cfg.indent
    st = cfg.style
    if st in ('sharp','rounded','reinforced','ascii','grid'):
        v = '|' if st == 'ascii' else '│'
        return ind + v + v.join(pieces) + v
    if st == 'ascii2':
        return ind + ' ' + '|'.join(pieces) + ' '
    if st == 'markdown':
        return ind + '|' + '|'.join(pieces) + '|'
    # none
    return ind + ''.join(pieces)


def render_table(header, body, cfg):
    has_header = not cfg.no_headers
    widths_content = compute_widths(header, body, has_header, cfg.number, cfg.sniff)
    widths = [w + 2 * cfg.padding for w in widths_content]
    out = []
    st = cfg.style

    def make_header_vals():
        vals = list(header)
        if cfg.number:
            vals = ['#'] + vals
        return vals
    def make_body_vals(row, idx):
        vals = list(row)
        if cfg.number:
            vals = [str(idx)] + vals
        return vals
    def header_aligns():
        return [cfg.header_align] * len(widths)
    def body_aligns():
        return [cfg.body_align] * len(widths)

    bordered = st in ('sharp','rounded','reinforced','ascii','grid')
    if bordered:
        out.append(line_bordered(widths, st, 'top', cfg.indent))

    if st == 'grid':
        rows = []
        if has_header:
            rows.append((make_header_vals(), header_aligns()))
        for idx, r in enumerate(body, 1):
            rows.append((make_body_vals(r, idx), body_aligns()))
        for ri, (vals, aligns) in enumerate(rows):
            out.append(render_row(vals, widths, cfg, aligns))
            if ri != len(rows) - 1:
                out.append(line_bordered(widths, st, 'sep', cfg.indent))
    else:
        if has_header:
            out.append(render_row(make_header_vals(), widths, cfg, header_aligns()))
            if body:
                if st in ('sharp','rounded','reinforced','ascii'):
                    out.append(line_bordered(widths, st, 'sep', cfg.indent))
                elif st == 'ascii2':
                    out.append(line_ascii2_sep(widths, cfg.indent))
                elif st == 'markdown':
                    out.append(line_markdown_sep(widths, cfg.indent))
        for idx, r in enumerate(body, 1):
            out.append(render_row(make_body_vals(r, idx), widths, cfg, body_aligns()))

    if bordered:
        out.append(line_bordered(widths, st, 'bottom', cfg.indent))
    return '\n'.join(out) + ('\n' if out else '')


def os_error_message(exc):
    # Rust's io::Error display: "... (os error N)" for common OS errors.
    msg = exc.strerror or os.strerror(exc.errno or 0)
    return f"csview: {msg} (os error {exc.errno})\n"


def read_input(cfg):
    if cfg.file is not None:
        try:
            with open(cfg.file, 'rb') as f:
                return f.read(), None
        except OSError as ex:
            return None, os_error_message(ex)
    try:
        return sys.stdin.buffer.read(), None
    except OSError as ex:
        return None, os_error_message(ex)


def line_start_positions(text):
    starts = [0]
    for idx, ch in enumerate(text):
        if ch == '\n':
            starts.append(idx+1)
    return starts


def parse_csv_records(data, cfg):
    # Decode as UTF-8. For invalid data, mimic the csv crate's common message sufficiently closely.
    try:
        text = data.decode('utf-8')
    except UnicodeDecodeError as ex:
        # Count line/byte roughly at failing byte.
        byte = ex.start
        prefix = data[:byte].decode('utf-8', 'ignore')
        line = prefix.count('\n') + 1
        eprint(f"csview: CSV parse error: record 0 (line {line}, field: 0, byte: {byte}): invalid utf-8: invalid UTF-8 in field 0 near byte index 0\n")
        return None, 1

    # csv.reader expects text stream; newline='' preserves csv semantics.
    stream = io.StringIO(text, newline='')
    reader = csv.reader(stream, delimiter=cfg.delimiter, quotechar='"', doublequote=True,
                        escapechar=None, skipinitialspace=False, strict=False)
    records = []
    expected = None
    # Approximate record starting positions for error messages.
    starts = line_start_positions(text)
    prev_line_num = 0
    try:
        for rec in reader:
            end_line = reader.line_num
            start_line = prev_line_num + 1
            # Python returns [] for empty physical lines; Rust csv ignores them.
            if len(rec) == 0:
                prev_line_num = end_line
                continue
            # csv crate also ignores truly empty first lines. Start byte approximation.
            bytepos = starts[start_line-1] if start_line-1 < len(starts) else len(text)
            rec_index = len(records)
            if expected is None:
                expected = len(rec)
            elif len(rec) != expected:
                eprint(f"csview: CSV error: record {rec_index} (line: {start_line}, byte: {bytepos}): found record with {len(rec)} fields, but the previous record has {expected} fields\n")
                return None, 1
            records.append(rec)
            prev_line_num = end_line
    except csv.Error as ex:
        eprint(f"csview: CSV error: {ex}\n")
        return None, 1

    if cfg.no_headers:
        header = []
        body = records
    else:
        if records:
            header = records[0]
            body = records[1:]
        else:
            header = []
            body = []
    return (header, body), 0


def run(cfg):
    data, err = read_input(cfg)
    if err:
        eprint(err); return 1
    parsed, code = parse_csv_records(data, cfg)
    if code:
        return code
    header, body = parsed
    sys.stdout.write(render_table(header, body, cfg))
    return 0


def main(argv):
    cfg, code = parse_args(argv)
    if code is not None:
        return code
    return run(cfg)

if __name__ == '__main__':
    sys.exit(main(sys.argv[1:]))
