def char_width(ch):
    o = ord(ch)
    if o == 0:
        return 0
    cat = unicodedata.category(ch)
    if cat.startswith('C'):
        # Treat format controls (ZWJ, variation selectors) and other controls as zero width.
        return 0
    if cat in ('Mn', 'Me'):
        return 0
    if unicodedata.east_asian_width(ch) in ('F', 'W'):
        return 2
    # Common emoji/default-wide pictographs not all marked W in older tables.
    if (0x1F000 <= o <= 0x1FAFF) or (0x2600 <= o <= 0x27BF):
        return 2
    return 1


def disp_width(s):
    return sum(char_width(ch) for ch in s)


def truncate_to_width(s, maxw):
    if maxw <= 0:
        return ''
    out = []
    w = 0
    for ch in s:
        cw = char_width(ch)
        if w + cw > maxw:
            break
        out.append(ch); w += cw
    return ''.join(out)


def align_text(s, width, align):
    w = disp_width(s)
    if w > width:
        s = truncate_to_width(s, width)
        w = disp_width(s)
    gap = max(0, width - w)
    if align == 'right':
        left, right = gap, 0
    elif align == 'center':
        left, right = gap // 2, gap - gap // 2
    else:
        left, right = 0, gap
    return ' ' * left + s + ' ' * right


def cell(s, content_width, padding, align):
    s = truncate_to_width(s, content_width)
    return ' ' * padding + align_text(s, content_width, align) + ' ' * padding


def compute_widths(header, body, has_header, number, sniff):
    sample_n = None if sniff == 0 else sniff
    if has_header:
        ncols = len(header)
    else:
        ncols = len(body[0]) if body else 0
    # Since validation guarantees fixed-length records, the first row/header establishes columns.
    widths = [0] * ncols
    def absorb(row):
        for idx, val in enumerate(row[:ncols]):
            widths[idx] = max(widths[idx], disp_width(val))
    if has_header:
        absorb(header)
        rows_to_sample = body if sample_n is None else body[:sample_n]
        for r in rows_to_sample: absorb(r)
    else:
        rows_to_sample = body if sample_n is None else body[:sample_n]
        for r in rows_to_sample: absorb(r)
