        numw = 0
        if has_header:
            numw = max(numw, 1)  # '#'
            count_rows = len(body) if sample_n is None else min(sample_n, len(body))
            for k in range(1, count_rows + 1):
                numw = max(numw, len(str(k)))
        else:
            count_rows = len(body) if sample_n is None else min(sample_n, len(body))
            for k in range(1, count_rows + 1):
                numw = max(numw, len(str(k)))
        widths = [numw] + widths
    return widths


def line_bordered(widths, style, kind, indent):
    # kind: top, sep, bottom
    if style == 'ascii':
        left = mid = right = '+'; h = '-'
    elif style == 'rounded':
        h = '─'
        if kind == 'top': left, mid, right = '╭','┬','╮'
        elif kind == 'bottom': left, mid, right = '╰','┴','╯'
        else: left, mid, right = '├','┼','┤'
    elif style == 'reinforced':
        h = '─'
        if kind == 'top': left, mid, right = '┏','┬','┓'
        elif kind == 'bottom': left, mid, right = '┗','┴','┛'
        else: left, mid, right = '├','┼','┤'
    else:  # sharp/grid
        h = '─'
        if kind == 'top': left, mid, right = '┌','┬','┐'
        elif kind == 'bottom': left, mid, right = '└','┴','┘'
        else: left, mid, right = '├','┼','┤'
    parts = [h * w for w in widths]
    return ' ' * indent + left + mid.join(parts) + right


def line_ascii2_sep(widths, indent):
    return ' ' * indent + ' ' + '+'.join('-' * w for w in widths) + ' '


def line_markdown_sep(widths, indent):
    return ' ' * indent + '|' + '|'.join('-' * w for w in widths) + '|'


def render_row(vals, widths, cfg, aligns, has_number_col=False):
    p = cfg.padding
    cwidths = [max(0, w - 2*p) for w in widths]
    pieces = []
    for i, w in enumerate(widths):
        val = vals[i] if i < len(vals) else ''
        align = aligns[i] if isinstance(aligns, list) else aligns
        pieces.append(cell(val, cwidths[i], p, align))
